-- The demo congregation in European Portuguese, for the help's pt-PT captures (scripts/help-captures/README.md).
-- Names, parts, sections, roles and document titles are data, not messages: run this on a copy of the French
-- scratch database, never on the French one and never on a real one. Terms follow
-- docs/development/translation-glossary.md and the app's pt-PT seed names.
DO $$ BEGIN
  IF current_database() NOT LIKE '%captures%' THEN RAISE EXCEPTION 'Not a capture database: %', current_database(); END IF;
END $$;

UPDATE "Congregation" SET name = 'A Minha Congregação', "displayName" = CASE WHEN "displayName" IS NULL THEN NULL ELSE 'A Minha Congregação' END, locale = 'pt-PT';
UPDATE "EventTemplate" t SET "name" = v.pt FROM (VALUES ('Réunion de semaine', 'Reunião de semana'), ('Réunion du week-end', 'Reunião de fim de semana'), ('Mémorial', 'Memorial'), ('Absence', 'Ausência'), ('Autre événement', 'Outro evento')) AS v(fr, pt) WHERE t."name" = v.fr;
