UPDATE "BuildingEntrance" SET notes = 'Caixas do correio no átrio. O porteiro está lá de manhã, exceto às quartas-feiras.' WHERE notes LIKE 'Boîtes aux lettres%';

-- The demo accounts read the app in European Portuguese.
UPDATE "UserAccount" SET locale = 'pt-PT' WHERE email LIKE '%@demo.unitae.app';
